import{CHAPTERS}from"../data/chapters.js";import{CONFIG}from"./config.min.js";class SearchManager{constructor(){this.searchIndex=[],this.input=null,this.results=null}init(){if(!CONFIG.showSearchButton){const t=document.getElementById("sidebarSearch");return void(t&&(t.style.display="none"))}this.input=document.getElementById("sidebarSearchInput"),this.results=document.getElementById("sidebarSearchResults"),this.input&&this.results&&(this.buildIndex(),this.setupEventListeners())}buildIndex(){this.searchIndex=[],CHAPTERS.forEach(t=>{this.searchIndex.push({chapterId:t.id,title:t.title,type:"title",text:t.title});t.content.split("\n\n").filter(t=>t.trim()).forEach((e,s)=>{if("---"===e||"***"===e)return;const n=this.stripHtml(e);n.length>0&&this.searchIndex.push({chapterId:t.id,title:t.title,type:"content",text:n,paragraphIndex:s})})})}stripHtml(t){const e=document.createElement("div");return e.innerHTML=t,e.textContent||e.innerText||""}setupEventListeners(){this.input.addEventListener("input",t=>{this.search(t.target.value)}),this.results.addEventListener("click",t=>{const e=t.target.closest(".sidebar-search-result");if(e){const t=parseInt(e.dataset.chapterId);this.navigateToResult(t)}})}search(t){const e=t.trim().toLowerCase();if(e.length<2)return void(this.results.innerHTML="");const s=[],n=new Set;this.searchIndex.forEach(t=>{if(t.text.toLowerCase().includes(e)){const e=t.chapterId;n.has(e)||(n.add(e),s.push(t))}});const i=s.slice(0,10);this.displayResults(i,e)}displayResults(t,e){if(0===t.length)return void(this.results.innerHTML='<div class="sidebar-search-empty">No results</div>');const s=t.map(t=>`<div class="sidebar-search-result" data-chapter-id="${t.chapterId}">${t.title}</div>`).join("");this.results.innerHTML=s}navigateToResult(t){this.input.value="",this.results.innerHTML="";const e=document.getElementById("tocSidebar"),s=document.getElementById("overlay");e&&e.classList.remove("open"),s&&s.classList.remove("active"),document.body.style.overflow="",window.location.hash=`chapter-${t}`}}const searchManager=new SearchManager;"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>searchManager.init()):searchManager.init();export{searchManager};